    OR (saved->>'personal_revision')::bigint<>(original->>'personal_revision')::bigint+2 THEN RAISE EXCEPTION 'Unexpected Kuroko personal change'; END IF;
 INSERT INTO watching.progress_corrections(operation_key,operation_hash,user_id,org_id,media_item_id,work_key,before_state,after_state,reason)
 VALUES((p->'command'->>'operation_key')::uuid,md5((p->'command')::text),item.user_id,item.org_id,item.id,'tv:45783',original,saved,p->'command'->>'reason');
 outcome:=watching.observe_provider(p->'anilist');
 IF NOT coalesce((outcome->>'accepted')::boolean,false) OR outcome->>'classification' NOT IN ('BASELINE','CORRECTION') THEN
   RAISE EXCEPTION 'Kuroko verified75-episode mapping was not accepted: %',outcome; END IF;
END $repair$;
COMMIT;
